urlset:
{%- for sitemap_entry in entries %}

    {{ sitemap_entry.permalink | escape_xml | safe }}
    {%- if sitemap_entry.updated %}
    {{ sitemap_entry.updated }}
    {%- endif %}

{%- endfor %}
{#- Zola's own entries, and the measurements page, which .github/measurements.py copies into
    static/ before the build rather than Zola rendering it. #}
{%- if load_data(path="static/verge/measurements/index.html", format="plain", required=false) %}

    {{ config.base_url | escape_xml | safe }}/verge/measurements/

{%- endif %}
